sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float angle;
uniform float2 center;
uniform float style;
uniform float alpha;
uniform float blendMode;
uniform float offset;

half4 blend(half4 base, half4 copy, int mode) {
    if (mode == 3) {
        float a = copy.a + base.a * (1.0 - copy.a);
        half3 bc = base.a > 0.0001 ? base.rgb / base.a : half3(0.0);
        half3 cc = copy.a > 0.0001 ? copy.rgb / copy.a : half3(0.0);
        return half4(bc * cc * a, a);
    }
    if (mode == 4) {
        float a = copy.a + base.a * (1.0 - copy.a);
        half3 bc = base.a > 0.0001 ? base.rgb / base.a : half3(0.0);
        half3 cc = copy.a > 0.0001 ? copy.rgb / copy.a : half3(0.0);
        return half4((1.0 - (1.0 - bc) * (1.0 - cc)) * a, a);
    }
    if (mode == 2) return base + copy * (1.0 - base.a);
    return copy + base * (1.0 - copy.a);
}

half4 main(float2 coord) {
    float theta = radians(angle);
    float2 d = float2(cos(theta), sin(theta));
    float2 normal = float2(-sin(theta), cos(theta));
    float2 c = center * size;
    float2 v = coord - c;
    float2 mirrorCoord = c + reflect(v, normal) + normal * (offset * size);
    half4 base = image.eval(coord);
    half4 copy = image.eval(mirrorCoord) * half(clamp(alpha, 0.0, 1.0));
    if (style < 0.5) {
        if (dot(v, normal) >= 0.0) return base;
        return copy + base * (1.0 - copy.a);
    }
    return blend(base, copy, int(round(blendMode)));
}
